                        ->whereMonth('att_date', $month)
                        ->whereYear('att_date', $year)
                        ->get();
            
                      foreach ($attendanceRecords as $attendance) {
                        $slotType->earned_amount += ($attendance->per_hr_cost * $batchDurationInHours);
                      }
                    }
                  }
