                        : $startDateChck->copy()->endOfMonth();
       
        $dayCountMonth = $startDateChck->diffInDays($endDateChck) + 1;
        

        for ($date = $startDate->copy(); $date <= $endDate; $date->addDay()) {

            // // ❌ Skip Sundays
