      ->whereMonth('incentive_month', $month)
      ->whereYear('incentive_month', $year)
      ->where('status', 0)
      ->first();

    if (!$incentive) {
      return 0;
    }

    $totalReward = 0;

    // Get goal data for this staff
    $goalData = GoalSetStaffModel::where('staff_id', $staff->sno)
      ->where('goal_month', $month)
      ->whereYear('goal_date', $year)
      ->first();

    if (!$goalData) {
      return 0;
    }

    // Calculate based on role
    if ($staff->role_id == 11) { // Sales Executive
      $customerCount = CustomerModel::where('branch_id', $branchId)
        ->whereYear('created_at', $year)
        ->whereMonth('created_at', $month)
        ->count();

      if ($customerCount >= ($goalData->conversion ?? 0)) {
        $totalReward += $incentive->tenx_award ?? 0;
      }

      // Add other reward calculations...

    } elseif ($staff->role_id == 12) { // Team Lead
      // Team lead calculation logic
    }

    return $totalReward;
  }



   public function getPIDetails(Request $request)
    {
        $staffId  = $request->query('staff_id');
        $monthRaw = $request->query('month');
        $year     = $request->query('year');
        $branchId = $request->query('branch_id');

        if (!$staffId || !$monthRaw || !$year || !$branchId) {
            return response()->json([
                'data' => [],
                'error' => 'Missing required parameters'
            ], 400);
        }

        $month = is_numeric($monthRaw)
            ? (int)$monthRaw
            : (int)date('m', strtotime($monthRaw . ' 1'));

        $gst_percent = 18;

        $staff = \App\Models\StaffModel::select(
                'et_staff.staff_name',
                'et_staff.role_id',
                'et_staff.staff_image',
                'et_department.department_name'
            )
            ->join('et_department', 'et_department.sno', '=', 'et_staff.department_id')
            ->where('et_staff.sno', $staffId)
            ->where('et_staff.branch_id', $branchId)
            ->where('et_staff.status', 0)
            ->first();
        if (!$staff) {
            return response()->json([
                'data' => [],
                'error' => 'Staff not found'
            ], 404);
        }

        $incentive = \App\Models\IncentiveModel::where('role_id', $staff->role_id)
            ->where('branch_id', $branchId)
            ->whereMonth('incentive_month', $month)
            ->whereYear('incentive_month', $year)
            ->where('status', 0)
            ->first();

        $pi_slabs = [];

        if ($incentive && $incentive->pi_slab_json) {
            $pi_slabs = json_decode($incentive->pi_slab_json, true);
        }

        $proposalIds = DB::table('et_customer')
            ->join('et_lead', 'et_lead.sno', '=', 'et_customer.lead_id')
            ->join('et_proposal', 'et_customer.sno', '=', 'et_proposal.customer_id')
            ->join('et_payment', function ($join) {
                $join->on('et_payment.proposal_id', '=', 'et_proposal.sno')
                    ->whereRaw('et_payment.transaction_date = (
                        SELECT MIN(ep.transaction_date)
                        FROM et_payment ep
                        WHERE ep.proposal_id = et_proposal.sno
                    )');
            })
            ->join('et_transaction', 'et_transaction.payment_id', '=', 'et_payment.sno')
            ->where('et_customer.status', 0)
            ->where('et_proposal.post_sale_check', 0)
            ->where('et_proposal.created_by', $staffId)
            ->whereYear('et_payment.transaction_date', $year)
            ->whereMonth('et_payment.transaction_date', $month)
            ->where('et_transaction.payment_status', 1)
            ->whereNotIn('et_proposal.proposal_status', [0, 1, 2])
            ->where('et_proposal.status', 0)
            ->pluck('et_proposal.sno');

            if ($proposalIds->isEmpty()) {
                return response()->json([
                    'data' => [],
                    'error' => 'No eligible proposals'
                ], 200);
            }

            $proposalDetails = collect();

            $overallSellingAmount = 0;
            $overallActualAmount = 0;

            $overallProfitNet = 0;
            $overallCollectionNet = 0;

            foreach ($proposalIds as $proposalId) {
                $proposal = DB::table('et_proposal')
                    ->join( 'et_country_currencies','et_proposal.currency_id', '=','et_country_currencies.sno')
                    ->join( 'et_customer','et_proposal.customer_id', '=','et_customer.sno')
                    ->where('et_proposal.sno', $proposalId)
                    ->select(
                        'et_proposal.*',
                        'et_customer.cus_name as customer_name',
                        'et_customer.cus_mobile',
                        'et_country_currencies.currency_symbol',
                        'et_country_currencies.currency_code'
                    )
                    ->first();

                $products = DB::table('et_proposal_product_cart')
                    ->join( 'et_product', 'et_product.sno', '=', 'et_proposal_product_cart.product_id' )
                    ->where( 'et_proposal_product_cart.proposal_sno', $proposalId)
                    ->select(
                        'et_product.product_name',
                        'et_proposal_product_cart.original_amount',
                        'et_proposal_product_cart.product_amount'
                    )
                    ->get();

                $packages = DB::table('et_proposal_package_cart')
                    ->join('et_product', 'et_product.sno', '=',  'et_proposal_package_cart.product_id' )
                    ->where( 'et_proposal_package_cart.proposal_sno',$proposalId)
                    ->select(
                        'et_product.product_name as package_name',
                        'et_proposal_package_cart.original_product_amount',
                        'et_proposal_package_cart.cust_product_amount'
                    )
                    ->get();

                $discountAmount = $proposal->discount_amount ?? 0 ;
 
                $totalOriginal = $products->sum('original_amount') + $packages->sum('original_product_amount');
                $totalCustom = ($products->sum('product_amount') + $packages->sum('cust_product_amount')) - $discountAmount;
 
                if ($totalCustom <= 0 || $totalOriginal <= 0) {
                    continue;
                }
 
                if ($totalCustom <= $totalOriginal) {
                    continue;
                }

                $profitOriginalCurrency = $totalCustom - $totalOriginal;

                if ($profitOriginalCurrency <= 0) {
                    continue;
                }

                $profitPercentage = ($profitOriginalCurrency / $totalCustom) * 100;

                $collectionOriginal = DB::table('et_transaction')
                    ->join( 'et_payment', 'et_transaction.payment_id', '=', 'et_payment.sno')
                    ->where('et_payment.proposal_id', $proposalId)
                    ->where('et_transaction.payment_status', 1)
                    ->sum('et_transaction.total_amount');

                $collectionINR = DB::table('et_transaction')
                    ->join( 'et_payment', 'et_transaction.payment_id', '=', 'et_payment.sno' )
                    ->where('et_payment.proposal_id', $proposalId)
                    ->where('et_transaction.payment_status', 1)
                    ->sum('et_transaction.total_amount_inr');

                if ($collectionOriginal <= 0 || $collectionINR <= 0) {
                    continue;
                }

              
                $conversionRate =  $collectionINR / $collectionOriginal;
                $profitINR = $profitOriginalCurrency * $conversionRate;
                $profitNet = $profitINR / 1.18;
                $collectionNet =$collectionINR / 1.18;
                $overallSellingAmount += $totalCustom;
                $overallActualAmount += $totalOriginal;
                $overallProfitNet += $profitNet;
                $overallCollectionNet += $collectionNet;

                
                $matchedSlab = 'No Matching Slab';
                $piRewardPercent = 0;

                foreach ($pi_slabs as $slab) {
                    $min = (float)$slab['min'];
                    $max = (float)$slab['max'];
                    if ($profitPercentage >= $min) {
                        $matchedSlab = $min . '% - ' . $max . '%';
                        $piRewardPercent = (float)$slab['percentage'];
                        if ($profitPercentage <= $max) {
                            break;
                        }
                    }
                }
                $piRewardAmount = ($profitNet * $piRewardPercent) / 100;

                $proposalDetails->push([
                    'proposal_id' => $proposal->sno,
                    'customer_name' => $proposal->customer_name,
                    'customer_mobile' => $proposal->cus_mobile,
                    'proposal_code' => $proposal->proposal_id,
                    'proposal_title' => $proposal->service_title ?? '-',
                    'product_package' => $proposal->product_package,
                    'products' => $products,
                    'packages' => $packages,
                    'currency_symbol' =>$proposal->currency_symbol,
                    'currency_code' =>  $proposal->currency_code,
                    'total_original' => round($totalOriginal),
                    'total_custom' => round($totalCustom),
                    'profit_net' => round($profitNet),
                    'profit_percentage' =>round($profitPercentage, 1),
                    'matched_slab' => $matchedSlab,
                    'pi_reward_percent' => $piRewardPercent,
                    'pi_reward_amount' => round($piRewardAmount),
                    'profit_net_original_without_gst' => round($profitOriginalCurrency),
                ]);
            }

            $overallProfitPercentage = 0;
            if ($overallSellingAmount > 0) {
                $overallProfitPercentage =
                    (
                        ($overallSellingAmount - $overallActualAmount)
                        / $overallSellingAmount
                    ) * 100;
            }

            $overallMatchedSlab = 'No Matching Slab';
            $overallPiPercent = 0;

            foreach ($pi_slabs as $slab) {
                $min = (float)$slab['min'];
                $max = (float)$slab['max'];
                if ($overallProfitPercentage >= $min) {
                    $overallMatchedSlab = $min . '% - ' . $max . '%';
                    $overallPiPercent = (float)$slab['percentage'];
                    if ($overallProfitPercentage <= $max) {
                        break;
                    }
                }
            }

        $overallPiAmount = ($overallProfitNet * $overallPiPercent) / 100;


        return response()->json([
            'staff' => $staff,
            'proposals' => $proposalDetails,
            'overall' => [
                'total_proposals' => $proposalDetails->count(),
                'collection_net' =>  round($overallCollectionNet),
                'profit_net' => round($overallProfitNet),
                'profit_percentage' =>round($overallProfitPercentage, 1),
                'matched_slab' => $overallMatchedSlab,
                'pi_percent' => $overallPiPercent,
                'pi_amount' =>  round($overallPiAmount),
            ]
        ]);
    }

